// Fetch all business metrics for today
const today = new Date().toISOString().split('T')[0];

return [{
  json: {
    report_date: today,
    report_type: 'daily_summary'
  }
}];

// Compile daily summary
const businessMetrics = $node["Get Daily Metrics"].json || [];
const emailMetrics = $node["Get Email Metrics"].json || [];
const taskMetrics = $node["Get Task Metrics"].json || [];
const today = new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });

let message = `📊 **Daily Business Summary**\n${today}\n\n`;

// Business Revenue
message += `💰 **Revenue**\n`;
let totalRevenue = 0;

for (const biz of businessMetrics) {
  const revenue = parseFloat(biz.revenue || 0);
  totalRevenue += revenue;
  const businessName = {
    'dj': '🎵 DJ Business',
    'woodys': '🎁 Woody\'s Creations',
    'bmf': '💼 BMF Work'
  }[biz.business] || biz.business;

  message += `${businessName}: £${revenue.toFixed(2)} (${biz.bookings_count} items)\n`;
}

message += `**Total: £${totalRevenue.toFixed(2)}**\n\n`;

// Email Activity
message += `📧 **Email Activity**\n`;
let totalEmails = 0;

for (const email of emailMetrics) {
  totalEmails += parseInt(email.email_count || 0);
  message += `${email.business_context}: ${email.email_count}\n`;
}

message += `**Total: ${totalEmails} emails**\n\n`;

// Task Status
message += `✅ **Tasks**\n`;
let totalTasks = 0;

for (const task of taskMetrics) {
  totalTasks += parseInt(task.task_count || 0);
  const statusEmoji = {
    'completed': '✅',
    'in_progress': '🔄',
    'pending': '⏳'
  }[task.status] || '📌';

  message += `${statusEmoji} ${task.status}: ${task.task_count}\n`;
}

message += `**Total: ${totalTasks} tasks**`;

return [{
  json: {
    message: message,
    total_revenue: totalRevenue,
    total_emails: totalEmails,
    total_tasks: totalTasks
  }
}];

// Analyze monthly revenue trends
const data = items.map(i => i.json);

// Group by business
const byBusiness = {
  'dj': { revenue: 0, count: 0 },
  'woodys': { revenue: 0, count: 0 },
  'bmf': { revenue: 0, count: 0 }
};

for (const row of data) {
  const biz = row.business;
  byBusiness[biz].revenue += parseFloat(row.revenue || 0);
  byBusiness[biz].count += parseInt(row.count || 0);
}

let message = `📊 **Monthly Revenue Report**\n`;
message += `Last 30 Days\n\n`;

let totalRevenue = 0;

for (const [biz, stats] of Object.entries(byBusiness)) {
  const businessName = {
    'dj': '🎵 DJ Business',
    'woodys': '🎁 Woody\'s Creations',
    'bmf': '💼 BMF Work'
  }[biz];

  const avgPerItem = stats.count > 0 ? stats.revenue / stats.count : 0;

  message += `**${businessName}**\n`;
  message += `💰 Revenue: £${stats.revenue.toFixed(2)}\n`;
  message += `📦 Items: ${stats.count}\n`;
  message += `📊 Avg: £${avgPerItem.toFixed(2)}\n\n`;

  totalRevenue += stats.revenue;
}

message += `**TOTAL REVENUE: £${totalRevenue.toFixed(2)}**\n\n`;

// Revenue breakdown percentage
message += `**Revenue Breakdown:**\n`;
for (const [biz, stats] of Object.entries(byBusiness)) {
  const percentage = totalRevenue > 0 ? (stats.revenue / totalRevenue * 100).toFixed(1) : 0;
  const businessName = {
    'dj': 'DJ',
    'woodys': 'Woody\'s',
    'bmf': 'BMF'
  }[biz];

  message += `${businessName}: ${percentage}%\n`;
}

return [{
  json: {
    message: message,
    total_revenue: totalRevenue,
    breakdown: byBusiness
  }
}];

// Format DJ performance metrics
const metrics = items.map(i => i.json);

if (metrics.length === 0) {
  return [{
    json: {
      message: "📭 No DJ metrics available"
    }
  }];
}

let message = `🎵 **DJ Business Performance**\nLast 90 Days\n\n`;

let totalBookings = 0;
let totalRevenue = 0;

for (const metric of metrics) {
  const count = parseInt(metric.booking_count || 0);
  const avgPrice = parseFloat(metric.avg_price || 0);
  const revenue = parseFloat(metric.total_revenue || 0);
  const avgDuration = parseFloat(metric.avg_duration || 0);

  message += `**${metric.event_type.toUpperCase()}**\n`;
  message += `📦 Bookings: ${count}\n`;
  message += `💰 Total: £${revenue.toFixed(2)}\n`;
  message += `📊 Avg Price: £${avgPrice.toFixed(2)}\n`;
  message += `⏱️ Avg Duration: ${avgDuration.toFixed(1)}h\n\n`;

  totalBookings += count;
  totalRevenue += revenue;
}

message += `**TOTALS**\n`;
message += `📦 Total Bookings: ${totalBookings}\n`;
message += `💵 Total Revenue: £${totalRevenue.toFixed(2)}\n`;
message += `📊 Avg per Booking: £${(totalRevenue / totalBookings).toFixed(2)}`;

return [{
  json: {
    message: message,
    total_bookings: totalBookings,
    total_revenue: totalRevenue
  }
}];

